import pytest

from app.io_utils import read_jsn, write_json


def test_write_read_roundtrip(tmp_path):
    p = tmp_path / "a.json"
    write_json(p, {"x": 1})
    assert read_jsn(p) == {"x": 1}

def test_utf8_read(tmp_path):
    p = tmp_path / "u.json"
    p.write_text('{"k": "caf\u00e9"}', encoding="utf-8")
    assert read_jsn(p)["k"] == "caf\u00e9"

